class HitCounter:
    def __init__(self):
        self.times = [0] * 300
        self.counts = [0] * 300

    def hit(self, t):
        i = t % 300
        if self.times[i] != t:
            self.times[i], self.counts[i] = t, 0
        self.counts[i] += 1

    def count(self, t):
        return sum(c for s, c in zip(self.times, self.counts) if t - 300 < s <= t)

