class _Node:
    def __init__(self):
        self.children = {}
        self.text = None   # None for a folder, a string for a file
        self.total = 0     # characters in every file at or below this node


class FileSystem:
    def __init__(self):
        self.root = _Node()

    def _names(self, path):
        return [name for name in path.split('/') if name]

    def _chain(self, names):
        # the nodes from the root to the end of the path, or None if it is missing
        chain = [self.root]
        for name in names:
            child = chain[-1].children.get(name)
            if child is None:
                return None
            chain.append(child)
        return chain

    def _make(self, names):
        chain = [self.root]
        for name in names:
            chain.append(chain[-1].children.setdefault(name, _Node()))
        return chain

    def _add(self, chain, delta):
        for node in chain:
            node.total += delta

    def mkdir(self, path):
        self._make(self._names(path))

    def write(self, path, text):
        chain = self._make(self._names(path))
        node = chain[-1]
        self._add(chain[:-1], len(text) - node.total)
        node.text, node.total = text, len(text)

    def read(self, path):
        chain = self._chain(self._names(path))
        return None if chain is None else chain[-1].text

    def ls(self, path):
        names = self._names(path)
        chain = self._chain(names)
        if chain is None:
            return []
        if chain[-1].text is not None:
            return [names[-1]]
        return sorted(chain[-1].children)

    def rm(self, path):
        names = self._names(path)
        chain = self._chain(names)
        if not names or chain is None:
            return
        self._add(chain[:-1], -chain[-1].total)
        del chain[-2].children[names[-1]]

    def mv(self, src, dst):
        s, d = self._names(src), self._names(dst)
        chain = self._chain(s)
        if not s or chain is None or self._chain(d) is not None or d[:len(s)] == s:
            return False
        node = chain[-1]
        self._add(chain[:-1], -node.total)
        del chain[-2].children[s[-1]]
        target = self._make(d[:-1])
        target[-1].children[d[-1]] = node
        self._add(target, node.total)
        return True

    def size(self, path):
        chain = self._chain(self._names(path))
        return 0 if chain is None else chain[-1].total

