def run_fs(ops):
    fs = FileSystem()
    out = []
    for op, *args in ops:
        result = getattr(fs, op)(*args)
        if op in ('read', 'ls', 'mv', 'size'):
            out.append(result)
    return out

def big_case(n=100000):
    state = [3141]
    def rnd(m):
        state[0] = (state[0] * 6364136223846793005 + 1442695040888963407) % 2**64
        return (state[0] >> 33) % m
    def folder(lo, hi):
        return '/' + '/'.join('abcdefgh'[rnd(8)] for _ in range(lo + rnd(hi - lo + 1)))
    def file():
        return folder(1, 3) + '/' + 'abcdefgh'[rnd(8)] + '.t'
    fs = FileSystem()
    sizes = moved = listed = read = 0
    for _ in range(n):
        r = rnd(40)
        if r < 14:
            fs.write(file(), 'x' * rnd(50))
        elif r < 16:
            fs.mkdir(folder(1, 4))
        elif r < 17:
            fs.rm(file() if rnd(2) else folder(2, 4))
        elif r < 21:
            if rnd(2):
                moved += fs.mv(file(), file())
            else:
                moved += fs.mv(folder(1, 3), folder(1, 3))
        elif r < 23:
            listed += len(fs.ls(folder(0, 3)))
        elif r < 25:
            read += len(fs.read(file()) or '')
        else:
            sizes += fs.size(folder(0, 1))
    return [sizes, moved, listed, read]
